import {requireUploadAccess} from './upload-auth.js';
const section=document.createElement('section');section.style.cssText='margin-top:32px;padding:22px;border:1px solid #ffffffc0;border-radius:22px;background:#ffffff80';section.innerHTML='<h2>讲解背景音乐</h2><input type="file" accept="audio/*,.mp3,.wav,.m4a,.aac,.flac,.ogg,.aiff,.wma" aria-label="讲解背景音乐"><label style="display:block;margin:16px 0">音量 <input type="range" min="0" max="50" value="12" aria-label="背景音乐音量"> <span>12%</span></label><button type="button">上传并使用</button><progress max="100" value="0" hidden style="width:100%;margin-top:16px"></progress><p role="status"></p><audio controls hidden style="max-width:100%"></audio>';
document.querySelector('main').append(section);const file=section.querySelector('[type=file]'),volume=section.querySelector('[type=range]'),button=section.querySelector('button'),progress=section.querySelector('progress'),status=section.querySelector('[role=status]'),preview=section.querySelector('audio');volume.oninput=()=>{section.querySelector('span').textContent=volume.value+'%';preview.volume=Number(volume.value)/100;};
fetch('/api/lecture-music').then(r=>r.json()).then(d=>{if(d.url){preview.src=d.url;preview.hidden=false;volume.value=Math.round(d.volume*100);volume.oninput();status.textContent='已保存背景音乐';}}).catch(()=>{});
button.onclick=async()=>{if(!file.files[0]){status.textContent='请先选择音乐文件';return;}try{await requireUploadAccess();button.disabled=true;progress.hidden=false;progress.value=0;status.textContent='正在上传';let d=await new Promise((resolve,reject)=>{const xhr=new XMLHttpRequest();xhr.open('POST','/api/lecture-music');xhr.timeout=180000;xhr.setRequestHeader('X-Music-Volume',Number(volume.value)/100);xhr.upload.onprogress=e=>{if(e.lengthComputable)progress.value=e.loaded/e.total*90;};xhr.upload.onload=()=>status.textContent='上传完成，正在准备音频';xhr.onload=()=>{let d;try{d=JSON.parse(xhr.responseText);}catch{return reject(Error('服务器返回无效响应'));}xhr.status<300?resolve(d):reject(Error(d.error||'上传失败'));};xhr.onerror=()=>reject(Error('上传连接中断'));xhr.ontimeout=()=>reject(Error('音频准备超时，请重试'));xhr.send(file.files[0]);});if(d.job){const job=d.job;for(let n=0;n<180;n++){await new Promise(r=>setTimeout(r,1500));const r=await fetch('/api/lecture-music?job='+encodeURIComponent(job),{cache:'no-store',signal:AbortSignal.timeout(10000)});d=await r.json();progress.value=90+(d.progress||0)*.1;status.textContent=d.detail||'正在准备背景音乐';if(d.status==='failed')throw Error(d.error);if(d.status==='complete')break;}if(d.status!=='complete')throw Error('音频处理时间较长，请稍后刷新查看结果');}progress.value=100;preview.src=d.url;preview.volume=d.renderedVolume!==undefined?1:d.volume;preview.hidden=false;status.textContent='已保存，将用于导师讲解';}catch(e){status.textContent=e.message;}finally{button.disabled=false;}};
